import 'package:dio/dio.dart';
import 'package:retrofit/retrofit.dart';

part 'poke_api_service.g.dart';

/// Typed PokeAPI client generated by `retrofit_generator`.
///
/// Endpoints return the raw JSON body (`Map<String, dynamic>`) so feature
/// datasources keep full control of model mapping (they already own the DTO
/// `fromJson` logic). This service is an alternative transport to
/// `DioApiClient` for teams that prefer typed, annotation-driven endpoints.
///
/// The return type is written as the literal `Map<String, dynamic>` rather than
/// a typedef alias: retrofit special-cases that exact type to return the
/// decoded body untouched.
@RestApi()
abstract class PokeApiService {
  factory PokeApiService(Dio dio, {String? baseUrl}) = _PokeApiService;

  /// GET `/pokemon?offset=&limit=` — a page of the Pokemon index.
  ///
  /// Returns the full [HttpResponse] so callers read the raw decoded body via
  /// `response.data` and own their own model mapping.
  @GET('/pokemon')
  Future<HttpResponse<dynamic>> getPokemonList({
    @Query('offset') required int offset,
    @Query('limit') required int limit,
  });

  /// GET `/pokemon/{name}` — full detail for a single Pokemon.
  @GET('/pokemon/{name}')
  Future<HttpResponse<dynamic>> getPokemon(@Path('name') String name);
}
